package ru.transferservis.admin.data;
import android.content.Context;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public final class AssessmentRepositoryInstrumentationTest {
    final Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();final AdminSessionStore store=new AdminSessionStore(context);VehicleAssessmentRepository repo;AssessmentServer server;long scope;
    @Before public void before()throws Exception {store.clear();server=new AssessmentServer();repo=new VehicleAssessmentRepository(context,server);assertTrue(store.save(ClassificationServer.session("original")));scope=repo.bind(AssessmentServer.ACTOR);}
    @After public void after(){repo.cancel();store.clear();}
    VehicleAssessment.Context load()throws Exception{return repo.load(scope,AssessmentServer.DRIVER,AssessmentServer.CAR).data;}
    VehicleAssessment.Parameters params(String year)throws Exception{return new VehicleAssessment.Parameters("Toyota","Camry",year,"hybrid","sedan");}
    VehicleAssessmentAction action(boolean exception)throws Exception {VehicleAssessment.Context c=load();VehicleAssessmentRepository.Read<VehicleAssessment.Selection> s=repo.select(scope,c,params("2023"),exception,exception?"Camry":"");return VehicleAssessmentAction.create(s.access,s.data,s.data.parameters,exception,s.data.basisModel,c.documents.get(0),c.documents.get(1),List.of("satisfied"),Set.of(),false,"Synthetic reason");}
    @Test public void assessmentUsesPinnedVersionUntilKeysChangeThenCurrentRule()throws Exception {VehicleAssessment.Context c=load();assertEquals("rule_native001",repo.select(scope,c,params("2023"),false,"").data.targetPinned);assertEquals(0,server.ruleReads.get());VehicleAssessment.Selection changed=repo.select(scope,c,params("2024"),false,"").data;assertEquals("rule_current001",changed.targetPinned);assertEquals("rule_current001:1",changed.conditions.get(0).id);assertEquals(1,server.ruleReads.get());assertEquals(0,server.commands.get());}
    @Test public void assessmentLostAckReadDoesNotRebaseExplicitOriginalRetry()throws Exception {VehicleAssessmentAction a=action(false);server.lostAck=true;try{repo.apply(a);fail();}catch(IOException expected){}assertEquals(1,server.commands.get());assertEquals(5,load().page.revision);VehicleAssessmentAction.Ack ack=repo.apply(a);assertEquals(5,ack.revision);assertEquals(2,server.commands.get());assertEquals(1,server.commits.get());assertEquals(a.key,server.lastKey);assertEquals(a.body().toString(),server.lastBody);}
    @Test public void assessmentRevokedGrantMfaAndPhoneScopeBlockBeforePost()throws Exception {VehicleAssessmentAction a=action(false);server.source.auth.verify=false;try{repo.apply(a);fail();}catch(AdminApiClient.Failure e){assertEquals(403,e.status);}server.source.auth.verify=true;server.source.auth.owner=true;VehicleAssessmentAction owner=action(true);assertEquals("rule_native001",owner.body().get("expectedRuleVersion").getAsString());assertEquals("rule_current001",owner.body().getAsJsonObject("exception").get("basisRuleVersion").getAsString());server.source.auth.mfa=false;try{repo.apply(owner);fail();}catch(AdminApiClient.Failure e){assertEquals(403,e.status);}server.source.auth.mfa=true;server.source.auth.phoneScope=true;try{repo.apply(a);fail();}catch(AdminApiClient.Failure e){assertEquals(403,e.status);}assertEquals(0,server.commands.get());}
    @Test public void assessment401503MalformedAckNeverRefreshOrReplay()throws Exception {VehicleAssessmentAction a=action(false);for(int status:new int[]{401,503}){server.failure=status;try{repo.apply(a);fail();}catch(AdminApiClient.Failure e){assertEquals(status,e.status);assertFalse(e.getMessage().contains("PRIVATE"));}}server.failure=0;server.wrongAck=true;try{repo.apply(a);fail();}catch(IOException expected){}assertEquals(3,server.commands.get());assertEquals(1,server.commits.get());assertNotNull(store.load());}
    @Test public void assessmentSessionReplacementAndCancelledScopeCannotWrite()throws Exception {VehicleAssessmentAction a=action(false);assertTrue(store.save(ClassificationServer.session("replacement")));try{repo.apply(a);fail();}catch(IOException expected){}assertEquals("synthetic-replacement",store.load().accessToken);assertEquals(0,server.commands.get());assertTrue(store.save(ClassificationServer.session("original")));scope=repo.bind(AssessmentServer.ACTOR);VehicleAssessmentAction b=action(false);repo.cancel();try{repo.apply(b);fail();}catch(IOException expected){}assertEquals(0,server.commands.get());}
    @Test public void assessmentStaleEvidenceConflictHasNoAutomaticGetOrPost()throws Exception {VehicleAssessmentAction a=action(false);int reads=server.reads.get();server.failure=409;try{repo.apply(a);fail();}catch(AdminApiClient.Failure e){assertEquals(409,e.status);}assertEquals(reads,server.reads.get());assertEquals(1,server.commands.get());assertEquals(0,server.commits.get());}
    @Test public void assessmentDocumentPreviewRequiresIndependentSensitivePermission()throws Exception {VehicleAssessment.Context c=load();server.sensitive=false;try{repo.preview(scope,c,c.documents.get(0));fail();}catch(AdminApiClient.Failure e){assertEquals(403,e.status);}assertEquals(0,server.resources.get());server.sensitive=true;assertTrue(repo.preview(scope,c,c.documents.get(0)).length>0);assertEquals(1,server.resources.get());}
    @Test public void assessmentLateReadCancellationCannotReturnContext()throws Exception {server.holdPath="/v1/admin/vehicles/"+AssessmentServer.CAR+"/classification";server.entered=new CountDownLatch(1);server.release=new CountDownLatch(1);ExecutorService executor=Executors.newSingleThreadExecutor();try{Future<?> pending=executor.submit(()->{try{load();throw new AssertionError("Late context returned");}catch(IOException expected){}catch(Exception e){throw new RuntimeException(e);}});assertTrue(server.entered.await(5,TimeUnit.SECONDS));repo.cancel();server.release.countDown();pending.get(8,TimeUnit.SECONDS);}finally{server.release.countDown();executor.shutdownNow();}assertEquals(0,server.commands.get());}
}
